param([switch]$NoOpen)
$ErrorActionPreference = 'Stop'
Set-Location -LiteralPath $PSScriptRoot
$out = Join-Path $PSScriptRoot 'results'
New-Item -ItemType Directory -Force -Path $out | Out-Null
function Html($v) { [System.Net.WebUtility]::HtmlEncode([string]$v) }
function Table($rows, $columns) {
    $items = @($rows)
    if ($items.Count -eq 0) { return '<p>无</p>' }
    $s = '<table><thead><tr>'
    foreach ($c in $columns) { $s += '<th>' + (Html $c) + '</th>' }
    $s += '</tr></thead><tbody>'
    foreach ($r in $items) {
        $s += '<tr>'
        foreach ($c in $columns) { $s += '<td>' + (Html $r.$c) + '</td>' }
        $s += '</tr>'
    }
    return $s + '</tbody></table>'
}
try {
    $files = @(Get-ChildItem -LiteralPath (Join-Path $PSScriptRoot 'inputs') -File -Filter '*.csv' | Sort-Object Name)
    if (!$files.Count) { throw 'inputs 中没有 CSV 文件。请放入导出后重试。' }
    $required = @('registration_id','participant_id','name','session','status','updated_at')
    $records = @(); $issues = @(); $sources = @(); $blocked = @{}
    foreach ($f in $files) {
        $rows = @(Import-Csv -LiteralPath $f.FullName -Encoding UTF8)
        if (!$rows.Count) { throw "文件为空或没有数据：$($f.Name)" }
        $headers = @($rows[0].PSObject.Properties.Name)
        foreach ($c in $required) { if ($headers -notcontains $c) { throw "文件 $($f.Name) 缺少列：$c" } }
        $sources += [pscustomobject]@{'文件'=$f.Name;'数据行数'=$rows.Count;'SHA256'=(Get-FileHash -LiteralPath $f.FullName -Algorithm SHA256).Hash}
        $line = 1
        foreach ($r in $rows) {
            $line++
            $reason = @()
            foreach ($c in $required) {
                $r.$c = ([string]$r.$c).Trim()
                if (!$r.$c) { $reason += "空字段 $c" }
            }
            if ($r.status -cnotin @('confirmed','pending','cancelled')) { $reason += '未知状态' }
            $t = [datetime]::MinValue
            if (![datetime]::TryParseExact($r.updated_at,'yyyy-MM-ddTHH:mm:ss',[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::None,[ref]$t)) { $reason += '时间格式错误' }
            if ($reason.Count) {
                $issues += [pscustomobject]@{'位置'="$($f.Name):$line";'报名编号'=$r.registration_id;'问题'=($reason -join '；')}
                if ($r.registration_id) { $blocked[$r.registration_id] = $true }
                continue
            }
            $records += [pscustomobject]@{registration_id=$r.registration_id;participant_id=$r.participant_id;name=$r.name;session=$r.session;status=$r.status;updated_at=$r.updated_at;source="$($f.Name):$line"}
        }
    }
    $current = @(); $conflicts = @(); $duplicateCount = 0
    foreach ($group in @($records | Group-Object registration_id)) {
        $latest = ($group.Group | Sort-Object updated_at -Descending | Select-Object -First 1).updated_at
        $top = @($group.Group | Where-Object updated_at -eq $latest)
        $variants = @($top | Group-Object participant_id,name,session,status,updated_at)
        $duplicateCount += $top.Count - $variants.Count
        if ($variants.Count -gt 1 -or $blocked.ContainsKey($group.Name)) {
            $conflicts += [pscustomobject]@{'报名编号'=$group.Name;'原因'=$(if ($blocked.ContainsKey($group.Name)) {'该编号存在无效数据，暂不计入'} else {'相同最新时间内容冲突，暂不计入'});'来源'=($group.Group.source -join '；')}
        } else { $current += $top[0] }
    }
    $confirmed = @($current | Where-Object status -eq confirmed)
    $pending = @($current | Where-Object status -eq pending)
    $cancelled = @($current | Where-Object status -eq cancelled)
    $people = @($confirmed.participant_id | Sort-Object -Unique).Count
    $sessions = @($current.session | Sort-Object -Unique)
    $prep = @(); $attention = @()
    foreach ($s in $sessions) {
        $yes = @($confirmed | Where-Object session -eq $s)
        $wait = @($pending | Where-Object session -eq $s)
        $no = @($cancelled | Where-Object session -eq $s)
        $n = @($yes.participant_id | Sort-Object -Unique).Count
        $potential = @(@($yes.participant_id) + @($wait.participant_id) | Sort-Object -Unique).Count
        $prep += [pscustomobject]@{'场次'=$s;'确认人数'=$n;'确认报名人次'=$yes.Count;'待确认人次'=$wait.Count;'取消人次'=$no.Count;'含待确认人数上限'=$potential;'准备建议'="以 $n 人为已确认准备基数；待确认全部确认时涉及 $potential 人。容量、物资及份额标准需人工确定。"}
    }
    foreach ($r in $pending) { $attention += [pscustomobject]@{'事项'='待确认报名';'编号'=$r.registration_id;'人员'="$($r.name) ($($r.participant_id))";'场次'=$r.session;'处理建议'='人工核实参加意向，待后续导出更新状态'} }
    foreach ($g in @($current | Group-Object participant_id,session | Where-Object Count -gt 1)) {
        $attention += [pscustomobject]@{'事项'='同人同场多条报名';'编号'=($g.Group.registration_id -join '、');'人员'=$g.Group[0].participant_id;'场次'=$g.Group[0].session;'处理建议'='核实是否重复报名；人数已按人员编号去重，人次保留'}
    }
    $labels = @{confirmed='已确认';pending='待确认';cancelled='已取消'}
    $detail = @($current | Sort-Object session,participant_id,registration_id | ForEach-Object {
        [pscustomobject]@{'报名编号'=$_.registration_id;'人员编号'=$_.participant_id;'姓名'=$_.name;'场次'=$_.session;'状态'=$labels[$_.status];'更新时间'=$_.updated_at;'采用来源'=$_.source}
    })
    $notice = if ($issues.Count -or $conflicts.Count) {'存在数据异常，以下为可确定记录的统计；异常编号暂不计入，请先处理。'} else {'所有数据通过格式及最新记录冲突检查。'}
    $html = @"
<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>活动报名整理结果</title>
<style>body{font:16px/1.6 "Microsoft YaHei",sans-serif;max-width:1200px;margin:32px auto;padding:0 20px;color:#193349;background:#f6f8fa}table{border-collapse:collapse;width:100%;background:white;margin:14px 0}td,th{border:1px solid #ccd6de;padding:9px;text-align:left;overflow-wrap:anywhere}th{background:#e5eef4}h1,h2{color:#164c67}.card{padding:18px;background:#fff;border-left:5px solid #23806f}small{color:#52616c}</style>
<h1>活动报名整理结果</h1><p>生成时间：$(Html (Get-Date -Format 'yyyy-MM-dd HH:mm:ss')) · 合成演示资料 · 本机离线整理</p>
<div class="card"><strong>确认参加：$people 人；确认报名：$($confirmed.Count) 人次</strong><br>待确认：$($pending.Count) 人次；已取消：$($cancelled.Count) 人次。<br>$(Html $notice)</div>
<h2>各场次准备</h2>$(Table $prep @('场次','确认人数','确认报名人次','待确认人次','取消人次','含待确认人数上限','准备建议'))
<p>各场次人数不能直接相加作为总人数：同一人可参加多个场次。没有签到资料，确认报名不代表实际到场；尚无容量或采购标准，不能判断超员或给出采购量。</p>
<h2>需要你处理</h2>$(Table $attention @('事项','编号','人员','场次','处理建议'))
<h2>数据冲突（暂不计入）</h2>$(Table $conflicts @('报名编号','原因','来源'))
<h2>格式问题（暂不计入）</h2>$(Table $issues @('位置','报名编号','问题'))
<h2>当前报名明细</h2>$(Table $detail @('报名编号','人员编号','姓名','场次','状态','更新时间','采用来源'))
<h2>来源与统计口径</h2><p>读取 inputs 中全部 UTF-8 CSV；按 registration_id 合并，按 updated_at 选最新版本，不按文件名判断新旧。完全相同的最新记录只采用一次（本次折叠 $duplicateCount 条）。同时间内容冲突或编号含无效行时暂停统计该编号。缺失于新快照不视为取消，取消须有明确状态。人员按 participant_id 去重，同名不合并。待确认人数上限仅表示当前已知记录全部确认的情形，不是预测。</p>
$(Table $sources @('文件','数据行数','SHA256'))<small>此页面为本次运行结果；每次成功运行会覆盖 results 内的结果，inputs 保持原样。读取失败时不覆盖原报告，并写入运行错误.txt。</small></html>
"@
    $html | Set-Content -LiteralPath (Join-Path $out '报名结果.html') -Encoding UTF8
    $detail | Export-Csv -LiteralPath (Join-Path $out '当前报名.csv') -Encoding UTF8 -NoTypeInformation
    $prep | Export-Csv -LiteralPath (Join-Path $out '场次准备.csv') -Encoding UTF8 -NoTypeInformation
    $errorFile = Join-Path $out '运行错误.txt'
    if (Test-Path -LiteralPath $errorFile) { Remove-Item -LiteralPath $errorFile }
    Write-Host "整理成功：确认 $people 人，$($confirmed.Count) 人次；待确认 $($pending.Count) 人次。"
    if (!$NoOpen) { Start-Process -FilePath (Join-Path $out '报名结果.html') }
} catch {
    $message = '本次整理失败，旧报告可能已过期。原因：' + $_.Exception.Message
    $message | Set-Content -LiteralPath (Join-Path $out '运行错误.txt') -Encoding UTF8
    Write-Host $message
    exit 1
}

