"""离线报名整理，仅使用 Python 标准库。"""
import csv
import html
import os
from pathlib import Path
import sys
from datetime import datetime
import webbrowser

ROOT = Path(__file__).resolve().parent
FIELDS = ['registration_id', 'participant_id', 'name', 'session', 'status', 'updated_at']
LABEL = {'confirmed': '已确认', 'pending': '待确认', 'cancelled': '已取消'}


def collect(folder):
    files = sorted(folder.glob('*.csv'))
    if not files:
        raise ValueError('inputs 中没有 CSV 文件。请放入报名导出后重试。')
    versions = {}
    count = 0
    for file in files:
        with file.open(encoding='utf-8-sig', newline='') as stream:
            reader = csv.DictReader(stream)
            if reader.fieldnames != FIELDS:
                raise ValueError(f'{file.name}：表头须按顺序为 {",".join(FIELDS)}')
            for line, raw in enumerate(reader, 2):
                if None in raw or any(raw.get(k) is None for k in FIELDS):
                    raise ValueError(f'{file.name}:{line}：列数不正确')
                row = {k: raw[k].strip() for k in FIELDS}
                try:
                    if not all(row.values()) or row['status'] not in LABEL:
                        raise ValueError('必填内容为空或状态不支持')
                    stamp = datetime.strptime(row['updated_at'], '%Y-%m-%dT%H:%M:%S')
                    if stamp.strftime('%Y-%m-%dT%H:%M:%S') != row['updated_at']:
                        raise ValueError('时间格式不正确')
                except ValueError as exc:
                    raise ValueError(f'{file.name}:{line}：{exc}') from exc
                row['source'] = f'{file.name}:{line}'
                versions.setdefault(row['registration_id'], []).append(row)
                count += 1
    current, conflicts = [], []
    for rid, rows in sorted(versions.items()):
        latest = max(r['updated_at'] for r in rows)
        winners = [r for r in rows if r['updated_at'] == latest]
        variants = {tuple(r[k] for k in FIELDS) for r in winners}
        if len(variants) > 1:
            conflicts.append((rid, winners))
        else:
            result = dict(winners[0])
            result['source'] = '；'.join(r['source'] for r in winners)
            current.append(result)
    return files, current, conflicts, count


def e(value):
    return html.escape(str(value), quote=True)


def table(headers, rows):
    return '<div class="scroll"><table><thead><tr>' + ''.join('<th>'+e(h)+'</th>' for h in headers) + '</tr></thead><tbody>' + ''.join('<tr>'+''.join('<td>'+e(c)+'</td>' for c in row)+'</tr>' for row in rows) + '</tbody></table></div>'


def render(files, rows, conflicts, count):
    confirmed = [r for r in rows if r['status'] == 'confirmed']
    pending = [r for r in rows if r['status'] == 'pending']
    people = len({r['participant_id'] for r in confirmed})
    cancelled = sum(r['status'] == 'cancelled' for r in rows)
    body = '<h1>活动报名整理</h1><p>合成演示资料 · 本机离线生成 · '+e(datetime.now().strftime('%Y-%m-%d %H:%M:%S'))+'</p>'
    if conflicts:
        body += '<p class="alert">存在同一报名、同一最新时间的内容冲突。以下统计不含冲突报名，不能作为完整总数。</p>'
    body += f'<div class="cards"><article><b>{people}</b>确认参加人数（跨场次去重）</article><article><b>{len(confirmed)}</b>已确认报名（人次）</article><article><b>{len(pending)}</b>待确认报名</article><article><b>{cancelled}</b>已取消报名</article></div>'
    body += '<h2>各场次准备依据</h2><p>建议按各场次已确认人数准备座位、资料；待确认人数另列，确认后再调整。未提供容量、物料份额或采购标准，不能判断超额或给出采购数量。确认报名不代表实际到场。</p>'
    summaries = []
    for session in sorted({r['session'] for r in rows}):
        members = [r for r in rows if r['session'] == session]
        sums = [len({r['participant_id'] for r in members if r['status'] == s}) for s in LABEL]
        summaries.append([session, *sums])
    body += table(['场次', '已确认人数', '待确认人数', '已取消人数'], summaries)
    body += '<p>各列均按人员编号去重；同一人员多条报名或不同状态需要核对，不能把各状态人数相加当作独立人数。</p><h2>需要处理</h2>'
    tasks = []
    for r in pending:
        tasks.append(['确认报名意向', r['registration_id'], r['name']+' / '+r['participant_id'], r['session'], r['source']])
    for rid, variants in conflicts:
        for r in variants:
            tasks.append(['核对同时间冲突：'+LABEL[r['status']], rid, r['name']+' / '+r['participant_id'], r['session'], r['source']])
    groups = {}
    for r in rows:
        if r['status'] != 'cancelled':
            groups.setdefault((r['participant_id'], r['session']), []).append(r)
    for (pid, session), group in groups.items():
        if len(group) > 1:
            tasks.append(['核对同人同场次多条有效报名', '、'.join(r['registration_id'] for r in group), pid, session, '；'.join(r['source'] for r in group)])
    names = {}
    for r in rows:
        names.setdefault(r['participant_id'], set()).add(r['name'])
    for pid, values in names.items():
        if len(values) > 1:
            tasks.append(['核对同一人员编号的不同姓名', '', pid, '、'.join(sorted(values)), '见下方当前记录'])
    body += table(['事项', '报名编号', '人员', '场次 / 说明', '来源'], tasks) if tasks else '<p>没有需要处理的报名问题。</p>'
    body += '<p>尚需你确定场地容量和物料标准。导出没有联系方式，本工具不会联系任何人。处理后请把修正的导出放回 inputs 再运行；无需删除历史导出。</p>'
    body += '<h2>当前报名记录</h2>' + table(['报名编号', '人员编号', '姓名', '场次', '状态', '更新时间', '来源文件:行'], [[r['registration_id'], r['participant_id'], r['name'], r['session'], LABEL[r['status']], r['updated_at'], r['source']] for r in rows])
    body += '<h2>统计口径与来源</h2><p>依据 inputs/导出说明.md：以 registration_id 合并全部快照，取 updated_at 最新内容；相同最新内容只计一次，相同最新时间的不同内容列为冲突。不因新文件未出现旧记录就视为取消。人数按 participant_id 去重，姓名仅展示。文件名和文件修改时间不决定状态。</p>'
    body += f'<p>读取 {len(files)} 个 CSV、{count} 行；合并为 {len(rows)+len(conflicts)} 条报名，其中 {len(conflicts)} 条冲突。最新记录更新时间：{e(max([r["updated_at"] for r in rows] + [v["updated_at"] for _, vs in conflicts for v in vs], default="无记录"))}。</p>'
    body += '<p>来源：'+e('、'.join(f.name for f in files))+'。规则核对依据：本地导出说明；运行时间见页首。</p>'
    return '<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>活动报名整理</title><style>body{font:16px/1.7 "Microsoft YaHei",sans-serif;color:#18313f;background:#f3f6f7;margin:0;padding:32px;max-width:1250px;margin:auto}h1{font-size:32px}h2{margin-top:32px}p{color:#425b66}.cards{display:flex;gap:16px;flex-wrap:wrap}article{background:white;padding:20px;border-radius:12px;flex:1;min-width:180px}b{display:block;font-size:38px;color:#087a70}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;background:white}th,td{text-align:left;padding:12px;border-bottom:1px solid #dde5e8}th{background:#e3eeef}td{overflow-wrap:anywhere}.alert{padding:16px;background:#ffe8be} @media print{body{padding:0;font-size:11px}.scroll{overflow:visible}th,td{padding:5px}}</style><main>'+body+'</main></html>'


def main():
    output = ROOT / 'outputs'
    output.mkdir(exist_ok=True)
    try:
        data = collect(ROOT / 'inputs')
        page = render(*data)
        temporary = output / 'result.tmp'
        temporary.write_text(page, encoding='utf-8')
        temporary.replace(output / 'result.html')
        (output / 'error.txt').unlink(missing_ok=True)
    except (ValueError, OSError, UnicodeError, csv.Error) as exc:
        message = '本次更新失败；上次结果未更新，请勿当作最新数据。\n'+str(exc)
        (output / 'error.txt').write_text(message, encoding='utf-8-sig')
        print(message)
        return 1
    print('更新完成：outputs/result.html')
    if '--no-open' not in sys.argv:
        webbrowser.open((output / 'result.html').as_uri())
    return 0


if __name__ == '__main__':
    sys.exit(main())

