        if (!$rows.Count) { throw ('文件为空或没有数据：' + $f.Name) }
        foreach ($key in $required) {
            if ($key -notin $rows[0].PSObject.Properties.Name) { throw ('文件缺少字段 ' + $key + '：' + $f.Name) }
        }
        $n = 1
        foreach ($r in $rows) {
            $n++
            $reason = ''
            foreach ($key in $required) {
                $r.$key = ([string]$r.$key).Trim()
                if (!$r.$key) { $reason += "缺少 $key；" }
            }
            $dt = [datetime]::MinValue
            if (![datetime]::TryParseExact($r.updated_at, 'yyyy-MM-ddTHH:mm:ss', [Globalization.CultureInfo]::InvariantCulture, [Globalization.DateTimeStyles]::None, [ref]$dt)) { $reason += '更新时间格式无效；' }
            if ($r.status -cnotin @('confirmed','pending','cancelled')) { $reason += '未知状态；' }
            $source = $f.Name + '：数据行 ' + ($n - 1)
            if ($reason) {
                $issues.Add([pscustomobject]@{id=$r.registration_id; detail=$reason; source=$source})
            }
            $records.Add([pscustomobject]@{registration_id=$r.registration_id; participant_id=$r.participant_id; name=$r.name; session=$r.session; status=$r.status; updated_at=$r.updated_at; time=$dt; source=$source; invalid=[bool]$reason})
        }
    }
    $current = New-Object System.Collections.Generic.List[object]
    $duplicateCount = 0
    foreach ($g in ($records | Where-Object registration_id | Group-Object -Property registration_id -CaseSensitive)) {
        # Invalid data for an ID blocks that ID: never silently fall back to an older state.
        if (@($g.Group | Where-Object invalid).Count) {
            $issues.Add([pscustomobject]@{id=$g.Name; detail='此报名含无效记录，整条报名暂不计入统计，请修正导出。'; source=($g.Group.source -join '；')})
            continue
        }
        $latestTime = ($g.Group | Sort-Object time -Descending | Select-Object -First 1).time
        $latest = @($g.Group | Where-Object { $_.time -eq $latestTime })
        $variants = @($latest | Group-Object -Property participant_id,name,session,status -CaseSensitive)
        $duplicateCount += $latest.Count - $variants.Count
        if ($variants.Count -gt 1) {
            $issues.Add([pscustomobject]@{id=$g.Name; detail='最新更新时间相同但内容冲突，暂不计入统计，请核对。'; source=($latest.source -join '；')})
            continue
        }
        $r = $latest[0]
        $r.source = $latest.source -join '；'
        $current.Add($r)
    }
    $confirmed = @($current | Where-Object status -CEQ 'confirmed')
    $pending = @($current | Where-Object status -CEQ 'pending')
    $cancelled = @($current | Where-Object status -CEQ 'cancelled')
    $people = @($confirmed | Group-Object participant_id -CaseSensitive).Count
    $sessions = @($current | Group-Object session -CaseSensitive | Sort-Object Name | ForEach-Object {
        $a = @($_.Group | Where-Object status -CEQ 'confirmed')
        $p = @($_.Group | Where-Object status -CEQ 'pending')
        [pscustomobject]@{session=$_.Name; confirmed=@($a | Group-Object participant_id -CaseSensitive).Count; registrations=$a.Count; pending=@($p | Group-Object participant_id -CaseSensitive).Count; cancelled=@($_.Group | Where-Object status -CEQ 'cancelled').Count}
    })
    foreach ($g in ($current | Group-Object participant_id,session -CaseSensitive)) {
        if ($g.Count -gt 1) { $issues.Add([pscustomobject]@{id=($g.Group.registration_id -join '、'); detail='同一人员在同一场次存在多条报名，请核对；场次人数已按人员编号去重。'; source=($g.Group.source -join '；')}) }
    }
    foreach ($g in ($current | Group-Object participant_id -CaseSensitive)) {
        if (@($g.Group | Group-Object name -CaseSensitive).Count -gt 1) { $issues.Add([pscustomobject]@{id=$g.Name; detail='同一人员编号对应不同姓名，请核对。'; source=($g.Group.source -join '；')}) }
    }
    $labels = @{confirmed='已确认';pending='待确认';cancelled='已取消'}
    $export = @($current | Sort-Object session,participant_id,registration_id | ForEach-Object {
        [pscustomobject]@{报名编号=$_.registration_id;人员编号=$_.participant_id;姓名=$_.name;场次=$_.session;状态=$labels[$_.status];更新时间=$_.updated_at;来源=$_.source}
    })
    $cols = @(@('报名编号','报名编号'),@('人员编号','人员编号'),@('姓名','姓名'),@('场次','场次'),@('状态','状态'),@('更新时间','更新时间'),@('来源','来源'))
    $pendingExport = @($export | Where-Object 状态 -EQ '待确认')
    $warning = if ($issues.Count) { '存在需核对数据；未解决的无效或冲突报名不计入人数，统计可能不完整。' } else { '数据检查通过。' }
    $html = @"
<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>活动报名整理结果</title>
<style>body{font-family:system-ui,'Microsoft YaHei',sans-serif;max-width:1200px;margin:32px auto;padding:0 20px;color:#183143;background:#f4f7fa}h1,h2{color:#133b54}section,.cards{background:white;padding:20px;border-radius:12px;margin:18px 0}table{border-collapse:collapse;width:100%;font-size:14px;display:block;overflow-x:auto}th,td{padding:10px;text-align:left;border-bottom:1px solid #ddd}th{background:#eaf1f6}strong{font-size:26px;color:#086b67}.note{color:#76500c}p{line-height:1.7}</style>
<h1>活动报名整理结果</h1><p>合成演示资料 · 本机离线生成 · 生成时间：$(HtmlEscape (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'))</p>
<div class="cards"><strong>$people 人确认参加</strong><p>确认报名 $($confirmed.Count) 条（跨场次人次）；待确认 $($pending.Count) 条；已取消 $($cancelled.Count) 条。人数按人员编号去重，同名不合并。</p><p class="note">$(HtmlEscape $warning)</p></div>
<section><h2>各场次准备</h2><p>以确认人数作为当前准备参考，待确认人数单列。尚无场地容量或采购标准，需由你确定；以下不是实际到场人数。</p>
$(Table $sessions @(@('session','场次'),@('confirmed','确认人数'),@('registrations','确认报名条数'),@('pending','待确认人数'),@('cancelled','取消条数')))</section>
<section><h2>需要你处理</h2><p>待确认报名 $($pending.Count) 条：请自行核对参加意向并更新后续导出。资料无联系方式，本工具不会联系任何人。</p>
$(if ($pending.Count) { Table $pendingExport $cols } else { '<p>没有待确认报名。</p>' })
<h3>数据核对事项（$($issues.Count) 项）</h3>$(if ($issues.Count) { Table $issues @(@('id','相关编号'),@('detail','处理事项'),@('source','来源')) } else { '<p>没有发现数据异常。</p>' })
<p>准备前请另行确定场地容量、物资及采购标准。</p></section>
<section><h2>当前报名明细</h2>$(Table $export $cols)</section>
<section><h2>统计口径与来源</h2><p>读取 inputs 中全部 UTF-8 CSV 快照，按 registration_id 合并，取 updated_at 最大的记录；文件名和文件修改时间不决定新旧。重复记录只计一次，最新时间相同而内容不同则列为冲突。旧快照中存在而新快照中未出现的报名保留，只有明确 cancelled 才算取消。同一人员跨场次分别计入场次人数，全局确认人数只算一次。</p><p>读取 $($files.Count) 个文件、$($records.Count) 条原始记录；合并后可统计报名 $($current.Count) 条。最新版本的重复副本 $duplicateCount 条已合并。明细保留所选版本来源，原文件未改动。</p><ul>$(($files | ForEach-Object { '<li>' + (HtmlEscape $_.Name) + '</li>' }) -join '')</ul></section></html>
"@
    $html | Set-Content -LiteralPath (Join-Path $out '报名汇总.html') -Encoding UTF8
    if ($export.Count) { $export | Export-Csv -LiteralPath (Join-Path $out '当前报名.csv') -NoTypeInformation -Encoding UTF8 }
    else { '"报名编号","人员编号","姓名","场次","状态","更新时间","来源"' | Set-Content -LiteralPath (Join-Path $out '当前报名.csv') -Encoding UTF8 }
    "更新成功：确认 $people 人；确认报名 $($confirmed.Count) 条；待确认 $($pending.Count) 条；已取消 $($cancelled.Count) 条；核对事项 $($issues.Count) 项。" | Set-Content -LiteralPath (Join-Path $out '运行状态.txt') -Encoding UTF8
    Write-Host "更新成功：确认 $people 人，结果位于 results。"
    if (!$NoOpen) { Start-Process -FilePath (Join-Path $out '报名汇总.html') }
} catch {
    $message = '更新失败：' + $_.Exception.Message + "`r`n请检查输入后重新运行。已有汇总可能是旧结果，请勿当作本次更新。"
    $message | Set-Content -LiteralPath (Join-Path $out '运行状态.txt') -Encoding UTF8
    Write-Host $message -ForegroundColor Red
    exit 1
}

