"""Run unchanged Skill delivery and inspect actual report data independently."""
import hashlib
from html.parser import HTMLParser
import json
from pathlib import Path
import shutil
import subprocess
import sys
from v2_roster_updates import OUT,HOLDOUT
from check_roster_reference import reconcile

class Tables(HTMLParser):
    def __init__(self):
        super().__init__();self.tables=[];self.table=None;self.row=None;self.cell=None;self.articles=[];self.article=None
    def handle_starttag(self,tag,attrs):
        if tag=='table':self.table=[]
        elif tag=='tr':self.row=[]
        elif tag in ('td','th'):self.cell=[]
        elif tag=='article':self.article=[]
    def handle_data(self,data):
        if self.cell is not None:self.cell.append(data)
        if self.article is not None:self.article.append(data)
    def handle_endtag(self,tag):
        if tag in ('td','th') and self.cell is not None:self.row.append(''.join(self.cell).strip());self.cell=None
        elif tag=='tr' and self.row is not None:self.table.append(self.row);self.row=None
        elif tag=='table' and self.table is not None:self.tables.append(self.table);self.table=None
        elif tag=='article' and self.article is not None:self.articles.append(self.article);self.article=None

source=OUT/'runs/r63/roster/V2/workspace';dest=OUT/'independent/V2'
